// types are defined in the IANA maintained IANA-MAU-MIB module, as
// OBJECT-IDENTITIES of dot3MauType. If the MAU type is unknown, the object
// identifier zeroDotZero is returned. This object represents the
// operational type of the MAU, as determined by either 1) the result of
// the auto-negotiation function or 2) if auto-negotiation is not enabled
// or is not implemented for this MAU, by the value of the object
// ifMauDefaultType. In case 2), a set to the object ifMauDefaultType will
// force the MAU into the new operating mode.
var IfMauType = snmp.NewColumn[snmp.OID](snmp.MustOID(1, 3, 6, 1, 2, 1, 26, 2, 1, 1, 3), snmp.KindObjectID, func(vb snmp.VarBind) (snmp.OID, error) {
	return snmp.DecodeOID(vb)
})

// IfMauStatus is the column ifMauStatus of table ifMauTable.
// The current state of the MAU. This object MAY be implemented as a
// read-only object by those agents and MAUs that do not implement software
// control of the MAU state. Some agents may not support setting the value
// of this object to some of the enumerated values. The value other(1) is
// returned if the MAU is in a state other than one of the states 2 through
// 6. The value unknown(2) is returned when the MAU's true state is
// unknown; for example, when it is being initialized. A MAU in the
// operational(3) state is fully functional; it operates, and passes
// signals to its attached DTE or repeater port in accordance to its
// specification. A MAU in standby(4) state forces DI and CI to idle and
// the media transmitter to idle or fault, if supported. Standby(4) mode
// only applies to link type MAUs. The state of ifMauMediaAvailable is
// unaffected. A MAU in shutdown(5) state assumes the same condition on DI,
// CI, and the media transmitter, as though it were powered down or not
// connected. The MAU MAY return other(1) value for the ifMauJabberState
// and ifMauMediaAvailable objects when it is in this state. For an AUI,
// this state will remove power from the AUI. Setting this variable to the
// value reset(6) resets the MAU in the same manner as a power-off,
// power-on cycle of at least one-half second would. The agent is not
// required to return the value reset(6). Setting this variable to the
// value operational(3), standby(4), or shutdown(5) causes the MAU to
// assume the respective state, except that setting a mixing-type MAU or an
// AUI to standby(4) will cause the MAU to enter the shutdown state.
var IfMauStatus = snmp.NewColumn[IfMauStatusValue](snmp.MustOID(1, 3, 6, 1, 2, 1, 26, 2, 1, 1, 4), snmp.KindInteger32, func(vb snmp.VarBind) (IfMauStatusValue, error) {
	v, err := snmp.DecodeInt32(vb)
	if err != nil {
		return IfMauStatusValue(0), err
	}
	return IfMauStatusValue(v), nil
})

// IfMauMediaAvailable is the column ifMauMediaAvailable of table ifMauTable.
// This object identifies Media Available state of the MAU, complementary
// to the ifMauStatus. Values for the standard IEEE 802.3 Media Available
// states are defined in the IANA maintained IANA-MAU-MIB module, as
